('U01',U,[1,128],'Ten item handler families; out-handler union and register qualification differ; direct/conditional lookup supplied by full HandlerHashSymbol definition; missing field confirm/canbattle true, missing onpokemon/battler false, missing field -1; bag fallback folds field true/false into1/0; quantity config off/missing returns1 and result min1.', ['WP28 §3.1','WP27 §5'],'Bag/menu/Ready/Party/Battle'),
